from typing import List
def parse_nested_parens(paren_string: str) -> List[int]:
    def parse_parens(s: str) -> List[int]:
        stack = []
        max_depth = 0
        current_depth = 0
        for char in s:
            if char == '(':
                stack.append(char)
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                stack.pop()
                current_depth -= 1
        return max_depth

    return [parse_parens(s) for s in paren_string.split()]

